-- ===========================================================================
-- 1. 0006_abuse_controls.sql
-- ===========================================================================
-- Bajeko Chiya Pasal — 0006_abuse_controls.sql
--
-- Abuse / integrity controls for the unauthenticated surface, following up on
-- 0005. Everything here is callable by guests by design, so the goal is to make
-- each call *cost something* instead of being free and unbounded.
--
-- 1. play_count manipulation.
--    `log_playback_event()` used to increment `songs.play_count` for anyone who
--    could hit /rest/v1/rpc/log_playback_event with a bare `anon` JWT — a
--    one-line loop could pump a song to the top of admin "most played". Now:
--      * a real listener identity is required (the frontend already calls
--        ensureListenerSession() first, so guests have an anonymous session),
--      * one listener counts at most once per song/event_type per 30 minutes,
--      * a listener may write at most 120 events/minute (flood guard).
--    Losing free telemetry is deliberate: client-supplied counts are only worth
--    recording when they are attributable.
--
-- 2. Takedown spam.
--    `submit_takedown()` was unlimited: one script could fill takedown_requests
--    with junk tickets (and the audit log with them). Now capped at 5 tickets
--    per hour per claimant email / per reporter session.
--
-- 3. Authz consistency.
--    The public `get_genre_categories(p_include_inactive)` let `anon` flip the
--    same toggle the admin-only `admin_genre_categories()` exposes. The public
--    one now always returns active rows; the parameter is kept only so the
--    signature (and the frontend call site) stays unchanged.

begin;

-- ---------------------------------------------------------------------------
-- Supporting columns + indexes for the throttles
-- ---------------------------------------------------------------------------

-- Who filed a takedown (null for a guest with no session).
alter table public.takedown_requests
    add column if not exists reporter_id uuid;

create index if not exists takedown_requests_email_time_idx
    on public.takedown_requests (claimant_email, created_at);
create index if not exists takedown_requests_reporter_time_idx
    on public.takedown_requests (reporter_id, created_at);

-- Drives both the per-minute flood guard and the 30-minute play_count dedup.
create index if not exists playback_events_session_time_idx
    on public.playback_events (session_id, timestamp);

-- ---------------------------------------------------------------------------
-- 1. log_playback_event: identified, deduplicated, rate-limited telemetry
-- ---------------------------------------------------------------------------

create or replace function public.log_playback_event(
    p_event_type text,
    p_song_id bigint default null,
    p_station_id bigint default null,
    p_error_message text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    v_session text;
    v_recent  integer;
    v_counted boolean := false;
begin
    -- Validate first so a bad enum is reported as such regardless of identity.
    if p_event_type not in ('start', 'complete', 'skip', 'error') then
        raise exception 'Invalid event_type %', p_event_type;
    end if;

    v_session := coalesce(auth.uid()::text, '');
    if v_session = '' then
        raise exception 'Session key or user authentication required';
    end if;

    -- Flood guard: telemetry is best effort, so drop quietly when a single
    -- listener is writing faster than any human possibly could.
    select count(*) into v_recent
    from public.playback_events
    where session_id = v_session
      and timestamp > now() - interval '1 minute';
    if v_recent >= 120 then
        return jsonb_build_object('status', 'throttled');
    end if;

    -- Decide BEFORE inserting, otherwise the row we are about to write would
    -- match its own dedup window. One increment per listener/song/30 minutes.
    if p_event_type in ('start', 'complete') and p_song_id is not null then
        select not exists (
            select 1
            from public.playback_events
            where session_id = v_session
              and song_id = p_song_id
              and event_type = p_event_type
              and timestamp > now() - interval '30 minutes'
        ) into v_counted;
    end if;

    insert into public.playback_events (event_type, song_id, station_id, session_id, error_message)
    values (
        p_event_type,
        p_song_id,
        p_station_id,
        v_session,
        left(coalesce(p_error_message, ''), 1000)
    );

    if v_counted then
        update public.songs set play_count = play_count + 1 where id = p_song_id;
    end if;

    return jsonb_build_object('status', 'recorded');
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. submit_takedown: bounded submissions per claimant identity
-- ---------------------------------------------------------------------------

create or replace function public.submit_takedown(
    p_song bigint,
    p_claimant_name text,
    p_claimant_email text,
    p_reason text,
    p_details text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    v_ticket_id bigint;
    v_uid       uuid := auth.uid();
    v_email     text;
    v_recent    integer;
begin
    if p_song is null then
        raise exception 'song: This field is required.';
    end if;
    if p_claimant_name is null or btrim(p_claimant_name) = '' then
        raise exception 'claimant_name: This field is required.';
    end if;
    if p_claimant_email is null
       or length(btrim(p_claimant_email)) > 320
       or p_claimant_email !~ '^[^@]+@[^@]+\.[^@]+$' then
        raise exception 'claimant_email: Enter a valid email address.';
    end if;
    if p_reason not in ('copyright', 'broken_video', 'wrong_metadata', 'other') then
        raise exception 'reason: Not a valid choice.';
    end if;
    if not exists (select 1 from public.songs where id = p_song) then
        raise exception 'song: Song not found.';
    end if;

    v_email := lower(btrim(p_claimant_email));

    -- Rate limit AFTER input validation so real validation errors keep
    -- reporting correctly, and so an invalid payload can never probe the
    -- throttle. 5/hour is plenty for a genuine rights holder.
    select count(*) into v_recent
    from public.takedown_requests
    where created_at > now() - interval '1 hour'
      and (claimant_email = v_email
           or (v_uid is not null and reporter_id = v_uid));
    if v_recent >= 5 then
        raise exception 'Too many reports from this identity in the last hour. Please try again later.';
    end if;

    insert into public.takedown_requests
        (song_id, claimant_name, claimant_email, reason, details, reporter_id)
    values (
        p_song,
        left(btrim(p_claimant_name), 200),
        v_email,
        p_reason,
        left(coalesce(p_details, ''), 5000),
        v_uid
    )
    returning id into v_ticket_id;

    insert into public.audit_logs (actor_username, action, target_model, target_id, details)
    values (
        'public_reporter',
        'TAKEDOWN_SUBMITTED',
        'Song',
        p_song::text,
        jsonb_build_object(
            'reason', p_reason,
            'ticket_id', v_ticket_id
        )
    );

    return jsonb_build_object(
        'message', 'Your report has been received and logged for review.',
        'ticket_id', v_ticket_id
    );
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Public taxonomy reads must not expose admin-only (inactive) rows
-- ---------------------------------------------------------------------------

create or replace function public.get_genre_categories(p_include_inactive boolean default false)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
    -- p_include_inactive is intentionally ignored here: admins have
    -- admin_genre_categories(), which is allowlist-guarded. Retaining the
    -- parameter keeps the existing signature and frontend call site intact.
    select coalesce(jsonb_agg(payload order by display_order, name), '[]'::jsonb)
    from (
        select
            c.display_order,
            c.name,
            jsonb_build_object(
                'id', c.id,
                'slug', c.slug,
                'name', c.name,
                'name_ne', c.name_ne,
                'description', c.description,
                'display_order', c.display_order,
                'is_active', c.is_active,
                'genres_count', (select count(*) from public.genres g where g.category = c.slug),
                'created_at', c.created_at
            ) as payload
        from public.genre_categories c
        where c.is_active
    ) t;
$$;

commit;


-- ===========================================================================
-- 2. 0007_festival_features.sql
-- ===========================================================================
-- Bajeko Chiya Pasal — 0007_festival_features.sql
-- Festival catalog section so visitors can pick an upcoming festival
-- and hear the best festive songs for it before the celebration.

begin;

-- ---------------------------------------------------------------------------
-- Festival taxonomy
-- ---------------------------------------------------------------------------
create table if not exists public.festival_categories (
    id              bigint generated by default as identity primary key,
    slug            text not null unique,
    name            text not null,
    name_ne         text not null default '',
    description     text not null default '',
    display_order   integer not null default 0,
    is_active       boolean not null default true,
    created_at      timestamptz not null default now()
);

-- Festival art is drawn with the custom SVG glyph set on the client
-- (frontend/src/components/FestivalGlyph.tsx). The old emoji column is retired;
-- this drops it from databases created before the glyph set existed.
alter table public.festival_categories drop column if exists emoji;

create index if not exists idx_festival_categories_display_order on public.festival_categories (display_order);
create index if not exists idx_festival_categories_is_active on public.festival_categories (is_active);

comment on table public.festival_categories is 'Seasonal festival catalog (Dashain, Tihar, Teej, ...).';
comment on column public.festival_categories.slug is 'URL-safe festival identifier.';

-- ---------------------------------------------------------------------------
-- Link songs to festivals (nullable; songs can live without a festival tag).
-- ---------------------------------------------------------------------------
alter table public.songs
    add column if not exists festival_id bigint
    references public.festival_categories (id) on delete set null;

create index if not exists idx_songs_festival_id on public.songs (festival_id);

-- ---------------------------------------------------------------------------
-- Festival category data
-- ---------------------------------------------------------------------------
-- Existing note: 'special' genre_categories row already describes "Festive & Seasonal".
-- We add a granular festival-level catalog for the UX section.
insert into public.festival_categories (id, slug, name, name_ne, description, display_order, is_active)
values
    -- Dashain (the biggest Nepali festival)
    (1, 'dashain', 'Dashain', 'दशैं',
     'मालश्रीको धुन, पिङ-चङ्गा, देउसी-भैलोको उल्लास।', 1, true),

    -- Tihar (festival of lights, deusi bhailo)
    (2, 'tihar', 'Tihar', 'तिहार',
     'लक्ष्मी पूजा, दीपमाला, भैलो बङ्गो, देउसी.', 2, true),

    -- Teej (women-centric monsoon festival)
    (3, 'teej', 'Teej', 'तीज',
     'तोली भरा, मेँझ्वरेटी, धुमधामका लोक ताल।', 3, true),

    -- Chitrabhan (Nepali New Year)
    (4, 'chitrabhan', 'Chitrabhan', 'चित्रबहिन',
     'Nepali New Year melodies and seasonal songs.', 4, true),

    -- Sonam Lhosar (Tamang New Year)
    (5, 'sonam-lhosar', 'Sonam Lhosar', 'सोनम ल्होसर',
     'Tamang New Year, lokal and folk sounds.', 5, true),

    -- Buddha Jayanti (Buddhist festival)
    (6, 'buddha-jayanti', 'Buddha Jayanti', 'बुद्ध जयंती',
     'Peaceful melodies, chants, and Buddhist heritage songs.', 6, true),

    -- Maha Shivaratri (Hindu holy night)
    (7, 'maha-shivaratri', 'Maha Shivaratri', 'महा शिवरात्रि',
     'Devotional and meditative Shiva-related songs.', 7, true)
on conflict (id) do nothing;

select setval(pg_get_serial_sequence('public.festival_categories', 'id'), (select max(id) from public.festival_categories));

-- NOTE: the seed-time links between festivals and songs live in seed.sql, not
-- here: migrations run *before* seed.sql, so referencing seeded song/artist ids
-- from a migration would violate foreign keys on a fresh database.

create or replace function public.get_festival_categories()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
    select coalesce(jsonb_agg(fc order by fc.display_order, fc.name), '[]'::jsonb)
    from public.festival_categories fc
    where fc.is_active;
$$;


-- Fetch the best-matching festive songs for a festival, sorted by play_count.
create or replace function public.get_festival_songs(p_festival_slug text, p_limit int default 24)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    v_count     bigint;
    v_results   jsonb;
    v_festival  bigint;
begin
    v_festival := (select id from public.festival_categories where slug = p_festival_slug and is_active);

    select count(*) into v_count
    from public.songs s
    where s.festival_id = v_festival
      and s.publication_status = 'published';

    select coalesce(jsonb_agg(sp.song order by sp.play_count desc nulls last, sp.id desc), '[]'::jsonb)
    into v_results
    from (
        select
            s.play_count as play_count,
            s.id as id,
            jsonb_build_object(
                'id', s.id,
                'title', s.title,
                'title_ne', s.title_ne,
                'artist_name', a.display_name,
                'artist_name_ne', a.display_name_ne,
                'primary_genre_name', g.name,
                'primary_genre_category', g.category,
                'mood_tags', s.mood_tags,
                'release_year', s.release_year,
                'duration_seconds', s.duration_seconds,
                'artwork_url', s.artwork_url,
                'play_count', s.play_count,
                'is_featured', s.is_featured,
                'featured_order', s.featured_order
            ) as song
        from public.songs s
        join public.artists a on a.id = s.artist_id
        left join public.genres g on g.id = s.primary_genre_id
        where s.festival_id = v_festival
          and s.publication_status = 'published'
        order by s.play_count desc nulls last, s.id desc
        limit least(greatest(coalesce(p_limit, 24), 1), 100)
    ) sp;

    return jsonb_build_object('count', v_count, 'results', v_results);
end;
$$;

commit;


-- ===========================================================================
-- 3. 0008_festival_calendar.sql
-- ===========================================================================
-- Bajeko Chiya Pasal — 0008_festival_calendar.sql
-- Turns "Festive & Seasonal" into a calendar-aware experience:
--
--   * every major Nepali festival is in the taxonomy (Dashain, Tihar, Chhath,
--     Teej, Maghe Sankranti, Maha Shivaratri, Holi, Ram Navami, Buddha Jayanti,
--     Janai Purnima, Krishna Janmashtami, Gaura Parva, Gai/Indra/Bisket Jatra,
--     the Losars, Yomari Punhi, Christmas, Eid, Udhauli/Ubhauli, ...)
--   * festival_dates stores the Gregorian window for each occurrence so the
--     site can count down to the *next* celebration and start the vibe ~20
--     days early
--   * get_festival_calendar() returns the whole calendar with days-until and
--     "imminent" flags
--   * get_festival_songs() now always returns a full, playable playlist by
--     falling back to thematically-close catalog songs when a festival has
--     few dedicated uploads yet.
--
-- Dates are lunar and shift every year, so they are data (not code): add a new
-- row per festival per year as the official gazette is published. When a
-- festival has no future row, get_festival_calendar() rolls the most recent
-- occurrence forward by a year and flags it as estimated so the section never
-- goes blank.

begin;

-- ---------------------------------------------------------------------------
-- Occurrence dates
-- ---------------------------------------------------------------------------
create table if not exists public.festival_dates (
    id           bigint generated by default as identity primary key,
    festival_id  bigint not null references public.festival_categories (id) on delete cascade,
    label        text not null default '',
    start_date   date not null,
    end_date     date not null,
    is_estimated boolean not null default false,
    created_at   timestamptz not null default now(),
    constraint festival_dates_span check (end_date >= start_date),
    constraint festival_dates_unique unique (festival_id, start_date)
);

create index if not exists idx_festival_dates_window on public.festival_dates (festival_id, start_date);

comment on table public.festival_dates is 'Gregorian date window for each occurrence of a festival (one row per festival per year).';
comment on column public.festival_dates.label is 'Human label for the occurrence, e.g. "BS 2083 / 2026".';

-- Match festivals to catalog songs for the always-full playlist fallback.
alter table public.festival_categories
    add column if not exists mood_tags text[] not null default '{}';

comment on column public.festival_categories.mood_tags is 'Theme tags used to fill a festival playlist when it has few dedicated songs.';

